#!/usr/bin/env bash
# Question 16: Forward ${Q16_ZONE} to the company DNS. Generated by Quick Create; variables arrive as environment variables.
set -euo pipefail

cur="$(kubectl -n kube-system get configmap coredns -o jsonpath='{.data.Corefile}')"
if [[ ! -f /root/.cka-coredns-Corefile ]]; then
  printf '%s\n' "$cur" > /root/.cka-coredns-Corefile
elif [[ "$cur" != "$(cat /root/.cka-coredns-Corefile)" ]]; then
  kubectl -n kube-system get configmap coredns -o json | jq --rawfile c /root/.cka-coredns-Corefile '.data.Corefile = $c' | kubectl replace -f - >/dev/null
  kubectl -n kube-system rollout restart deployment/coredns >/dev/null
  kubectl -n kube-system rollout status deployment/coredns --timeout=240s >/dev/null
fi
kubectl create namespace "${Q16_NS}" >/dev/null 2>&1 || kubectl get namespace "${Q16_NS}" >/dev/null
timeout 60 bash -c "until kubectl -n '${Q16_NS}' get serviceaccount default >/dev/null 2>&1; do sleep 1; done"
kubectl -n "${Q16_NS}" create deployment web --image=nginx:1.27-alpine --port=80 --dry-run=client -o yaml | kubectl apply -f - >/dev/null
kubectl -n "${Q16_NS}" expose deployment web --port=80 --dry-run=client -o yaml | kubectl apply -f - >/dev/null
kubectl -n "${Q16_NS}" delete pod dns-test --ignore-not-found --wait=true >/dev/null
kubectl -n "${Q16_NS}" run dns-test --image=busybox:1.36 -- sleep infinity >/dev/null
kubectl -n "${Q16_NS}" rollout status deployment/web --timeout=180s >/dev/null
kubectl -n "${Q16_NS}" wait --for=condition=Ready pod/dns-test --timeout=120s >/dev/null
kubectl create namespace "corp-dns" >/dev/null 2>&1 || kubectl get namespace "corp-dns" >/dev/null
timeout 60 bash -c "until kubectl -n 'corp-dns' get serviceaccount default >/dev/null 2>&1; do sleep 1; done"
image=$(kubectl -n kube-system get deployment coredns -o jsonpath='{.spec.template.spec.containers[0].image}')
kubectl apply -f - <<EOF >/dev/null
apiVersion: v1
kind: ConfigMap
metadata: { name: resolver, namespace: corp-dns }
data:
  Corefile: |
    ${Q16_ZONE}:5353 {
        errors
        hosts {
            ${Q16_IP} intranet.${Q16_ZONE}
        }
    }
    .:5353 {
        errors
        forward . /etc/resolv.conf
    }
---
apiVersion: apps/v1
kind: Deployment
metadata: { name: resolver, namespace: corp-dns }
spec:
  replicas: 1
  selector: { matchLabels: { app: resolver } }
  template:
    metadata: { labels: { app: resolver } }
    spec:
      # The node's resolvers, not the cluster DNS: forwarding back to CoreDNS would loop.
      dnsPolicy: Default
      containers:
        - name: coredns
          image: $image
          args: ["-conf", "/etc/coredns/Corefile"]
          ports:
            - { name: dns, containerPort: 5353, protocol: UDP }
            - { name: dns-tcp, containerPort: 5353, protocol: TCP }
          volumeMounts: [{ name: config, mountPath: /etc/coredns }]
      volumes:
        - name: config
          configMap: { name: resolver }
---
apiVersion: v1
kind: Service
metadata: { name: resolver, namespace: corp-dns }
spec:
  selector: { app: resolver }
  ports:
    - { name: dns, port: 53, targetPort: 5353, protocol: UDP }
    - { name: dns-tcp, port: 53, targetPort: 5353, protocol: TCP }
EOF
kubectl -n corp-dns rollout restart deployment/resolver >/dev/null
kubectl -n corp-dns rollout status deployment/resolver --timeout=180s >/dev/null
rip=$(kubectl -n corp-dns get service resolver -o jsonpath='{.spec.clusterIP}')
for _ in $(seq 1 30); do
  kubectl -n "${Q16_NS}" exec dns-test -- nslookup "intranet.${Q16_ZONE}" "$rip" 2>/dev/null | grep -qw "${Q16_IP}" && break
  sleep 2
done
kubectl -n "${Q16_NS}" exec dns-test -- nslookup "intranet.${Q16_ZONE}" "$rip" 2>/dev/null | grep -qw "${Q16_IP}" || { echo "the company resolver does not answer intranet.${Q16_ZONE}" >&2; exit 1; }
: "${Q16_NS}" "${Q16_DOMAIN}" "${Q16_ZONE}" "${Q16_HOST}" "${Q16_IP}"
